DROP TABLE IF EXISTS `wanchi3366_esg_emission_factors`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wanchi3366_esg_emission_factors` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `factor_code` varchar(50) NOT NULL COMMENT '係數代碼 (如 EF-ELEC-2023, EF-DIESEL-01)',
  `factor_name` varchar(150) NOT NULL COMMENT '係數名稱 (如 2023年度電力排碳係數)',
  `scope_type` enum('Scope1','Scope2','Scope3') NOT NULL COMMENT '溫室氣體範疇分類',
  `category` varchar(50) NOT NULL COMMENT '排放源類別 (固定燃燒, 移動燃燒, 電力, 水, 廢棄物, 差旅)',
  `fuel_type` varchar(50) DEFAULT NULL COMMENT '燃料/能源名稱 (柴油, 汽油, 天然氣, 電力)',
  `co2e_factor` decimal(14,6) NOT NULL COMMENT '每單位活動量之 CO2e 排放係數 (kg CO2e / 單位)',
  `unit` varchar(30) NOT NULL COMMENT '活動數據計量單位 (度, 公升, 公斤, 立方公尺, 公噸)',
  `data_source` varchar(150) NOT NULL COMMENT '係數公告來源 (如 環境部氣候變遷署 6.0.4 版 / IPCC AR6)',
  `effective_year` smallint(6) NOT NULL COMMENT '生效適用年份 (如 2023, 2024)',
  `is_current` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否為目前最新預設係數',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `factor_code` (`factor_code`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='溫室氣體碳排係數庫';
/*!40101 SET character_set_client = @saved_cs_client */;

