CREATE TABLE `wanchi3366_esg_ghg_emissions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `org_unit_id` int(10) unsigned NOT NULL COMMENT '填報廠區 / 部門 ID',
  `period_year` smallint(6) NOT NULL COMMENT '盤查年度 (如 2024)',
  `period_month` tinyint(4) NOT NULL COMMENT '盤查月份 (1-12)',
  `scope_type` enum('Scope1','Scope2','Scope3') NOT NULL COMMENT '範疇分類',
  `emission_source` varchar(120) NOT NULL COMMENT '具體排放源 (如 緊急發電機-1號機, 廠區外購電力)',
  `factor_id` int(10) unsigned NOT NULL COMMENT '引用係數 ID',
  `activity_amount` decimal(14,4) NOT NULL COMMENT '活動數據輸入量',
  `activity_unit` varchar(30) NOT NULL COMMENT '活動數據計量單位',
  `calculated_tco2e` decimal(14,4) NOT NULL COMMENT '核算結果: 排放當量 (公噸 CO2e)',
  `invoice_no` varchar(60) DEFAULT NULL COMMENT '發票號碼 / 收據號碼 / 電號',
  `proof_file_path` varchar(255) DEFAULT NULL COMMENT '佐證單據掃描檔上傳路徑',
  `workflow_status` enum('draft','pending','approved','rejected','locked') NOT NULL DEFAULT 'draft' COMMENT '審批狀態',
  `reviewer_id` bigint(20) unsigned DEFAULT NULL COMMENT '審核主管 ID',
  `reviewer_comment` varchar(255) DEFAULT NULL COMMENT '審核意見或退回原因',
  `reviewed_at` datetime DEFAULT NULL COMMENT '審核時間',
  `created_by` bigint(20) unsigned NOT NULL COMMENT '填報人 ID',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_ghg_org` (`org_unit_id`),
  KEY `fk_ghg_factor` (`factor_id`),
  KEY `fk_ghg_user` (`created_by`),
  KEY `idx_ghg_period` (`period_year`,`period_month`),
  KEY `idx_ghg_scope` (`scope_type`),
  KEY `idx_ghg_status` (`workflow_status`),
  CONSTRAINT `fk_ghg_factor` FOREIGN KEY (`factor_id`) REFERENCES `wanchi3366_esg_emission_factors` (`id`),
  CONSTRAINT `fk_ghg_org` FOREIGN KEY (`org_unit_id`) REFERENCES `wanchi3366_sys_org_units` (`id`),
  CONSTRAINT `fk_ghg_user` FOREIGN KEY (`created_by`) REFERENCES `wanchi3366_sys_users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=190 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='溫室氣體活動數據與碳排記錄主表';
