DROP TABLE IF EXISTS `wanchi3366_esg_governance_metrics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wanchi3366_esg_governance_metrics` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `period_year` smallint(6) NOT NULL COMMENT '統計年度',
  `board_seats_total` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT '董事會總席位',
  `independent_directors` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT '獨立董事席位',
  `female_directors` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT '女性董事席位',
  `board_meetings_count` tinyint(3) unsigned NOT NULL DEFAULT 0 COMMENT '董事會開會次數',
  `board_attendance_rate` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '董事平均出席率 (%)',
  `ethics_train_headcount` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '誠信經營受訓人次',
  `whistleblower_cases` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '舉報信箱受理件數',
  `whistleblower_closed` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '舉報案件結案數',
  `cyber_incidents_count` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '重大資安事件數',
  `legal_penalty_count` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '重大環保/勞動裁罰件數',
  `legal_penalty_amount` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT '罰鍰總金額 (NTD)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `period_year` (`period_year`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公司治理與誠信運作指標表';
/*!40101 SET character_set_client = @saved_cs_client */;

