DROP TABLE IF EXISTS `wanchi3366_esg_social_metrics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wanchi3366_esg_social_metrics` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `org_unit_id` int(10) unsigned NOT NULL,
  `period_year` smallint(6) NOT NULL,
  `male_employees` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '男性員工數',
  `female_employees` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '女性員工數',
  `disabled_employees` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '身障員工人數',
  `female_managers` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '女性主管人數',
  `total_work_hours` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT '總工作時數',
  `disabling_injury_count` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '失能傷害次數',
  `lost_days_count` int(10) unsigned NOT NULL DEFAULT 0 COMMENT '損失工作日數',
  `fr_value` decimal(8,4) NOT NULL DEFAULT 0.0000 COMMENT '失能傷害頻率 (FR)',
  `sr_value` decimal(8,4) NOT NULL DEFAULT 0.0000 COMMENT '失能傷害嚴重率 (SR)',
  `training_hours_total` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '員工培訓總時數',
  `volunteer_hours` decimal(10,2) NOT NULL DEFAULT 0.00 COMMENT '志工服務總時數',
  `donation_amount_ntd` decimal(14,2) NOT NULL DEFAULT 0.00 COMMENT '公益捐贈金額 (NTD)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_soc_org_year` (`org_unit_id`,`period_year`),
  CONSTRAINT `fk_soc_org` FOREIGN KEY (`org_unit_id`) REFERENCES `wanchi3366_sys_org_units` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='社會責任與人資職安指標表';
