DROP TABLE IF EXISTS `wanchi3366_sys_audit_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wanchi3366_sys_audit_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL COMMENT '操作人員 ID',
  `action_type` varchar(30) NOT NULL COMMENT '動作類型 (LOGIN, CREATE, UPDATE, DELETE, APPROVE, REJECT, EXPORT)',
  `target_table` varchar(50) NOT NULL COMMENT '影響之資料表',
  `record_id` bigint(20) unsigned DEFAULT NULL COMMENT '受影響紀錄之主鍵 ID',
  `old_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '異動前數據 (JSON)' CHECK (json_valid(`old_values`)),
  `new_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '異動後數據 (JSON)' CHECK (json_valid(`new_values`)),
  `ip_address` varchar(45) NOT NULL COMMENT '客戶端 IP 位址',
  `user_agent` varchar(255) DEFAULT NULL COMMENT '瀏覽器識別',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_audit_user` (`user_id`),
  KEY `idx_audit_action` (`action_type`),
  KEY `idx_audit_table` (`target_table`),
  KEY `idx_audit_time` (`created_at`),
  CONSTRAINT `fk_audit_user` FOREIGN KEY (`user_id`) REFERENCES `wanchi3366_sys_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系統全生命週期稽核軌跡日誌';
