--
-- Table structure for table `wanchi3366_sys_users`
--

DROP TABLE IF EXISTS `wanchi3366_sys_users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wanchi3366_sys_users` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '使用者 ID',
  `org_unit_id` int(10) unsigned NOT NULL COMMENT '所屬組織單位 ID',
  `role_id` int(10) unsigned NOT NULL COMMENT '所屬角色 ID',
  `username` varchar(50) NOT NULL COMMENT '登入帳號 / 員工編號',
  `password_hash` varchar(255) NOT NULL COMMENT '密碼雜湊值 (PHP password_hash)',
  `full_name` varchar(100) NOT NULL COMMENT '使用者中文姓名',
  `email` varchar(150) NOT NULL COMMENT '電子信箱 (審批通知)',
  `phone` varchar(30) DEFAULT NULL COMMENT '分機 / 聯絡電話',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '帳號狀態 (1: 啟用, 0: 停用, -1: 鎖定)',
  `failed_login_count` tinyint(4) NOT NULL DEFAULT 0 COMMENT '連續密碼錯誤次數',
  `last_login_at` datetime DEFAULT NULL COMMENT '最後登入時間',
  `last_login_ip` varchar(45) DEFAULT NULL COMMENT '最後登入 IP',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  KEY `fk_user_org` (`org_unit_id`),
  KEY `fk_user_role` (`role_id`),
  KEY `idx_user_email` (`email`),
  KEY `idx_user_status` (`status`),
  CONSTRAINT `fk_user_org` FOREIGN KEY (`org_unit_id`) REFERENCES `wanchi3366_sys_org_units` (`id`),
  CONSTRAINT `fk_user_role` FOREIGN KEY (`role_id`) REFERENCES `wanchi3366_sys_roles` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系統使用者帳號表';
/*!40101 SET character_set_client = @saved_cs_client */;

